import React from 'react';

class ManageRegistrationScreen extends React.Component {
    constructor(props) {
        super(props);
        this.state = {
            registrations: []
        };
    }

    componentDidMount() {
        // Fetch all prospects initially (optional)
        this.fetchProspects();
    }

    fetchProspects() {
        const { journeyID, accountStatus } = this.props; // Assuming journeyID and accountStatus are passed down props
        let promises = [];

        for(let i = 0; i < this.state.registrations.length; i++) {
            const registration = this.state.registrations[i];

            const headers = new Headers();
            headers.append('Authorization', 'Bearer ' + user.getAccessToken());

            const fetchOptions = {
                headers: headers,
                method: 'GET',
            };

            promises.push(
                fetch(`api/${this.props.productCode}/prospects/${registration.journeyID}`, fetchOptions)
                    .then(response => response.json())
                    .then(data => {
                        registration.prospectStatus = data.prospectStatus || -1;
                        registration.createDateTime = data.createDateTime || '';
                        registration.accountStatus = data.accountStatus || 5;
                        registration.accountCreateDateTime = data.accountCreateDateTime || '';

                        return data;
                    })
                    .catch(error => console.error('Error:', error))
            );
        }

        Promise.all(promises).then(() => {
            this.setState({
                registrations: this.state.registrations.map(registration => ({
                    ...registration,
                    portInStatus: 1 // or any other value you wish to add
                }))
            });
        }).catch(err => console.error('Failed to fetch prospects.', err));
    }

